SELECT subq_1.day AS day, COUNT(subq_1.positive_conversations_measure) AS positive_conversations, dim_agent.agent_team AS agent_team, dim_user.user_region AS location FROM (SELECT CASE WHEN fact_ticket_journey.csat_score >= 3 THEN fact_ticket_journey.ticket_id END AS positive_conversations_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, user_id AS user, final_agent_id AS agent, user_id AS user FROM fact_ticket_journey WHERE 1 = 1) AS subq_1 JOIN dim_agent AS dim_agent ON subq_1.agent = dim_agent.agent_id JOIN dim_user AS dim_user ON subq_1.user = dim_user.user_id GROUP BY day, location, agent_team